// First-person viewmodel presentation. Artwork is a generated fan reinterpretation;
// enemy imagery in spine-lite.js uses the original extracted game textures.
const FPS={swayX:0,swayY:0,kick:0,kickVelocity:0,attack:0,reloadTime:0,aim:0,step:0,shells:[],tracer:0,skillPulse:0};
let viewmodelImage=null,viewmodelReady=false;
function refreshAssetStatus(){const status=document.getElementById('assetStatus');if(status)status.textContent=EnemyAssets.error?'敌人贴图加载失败，请刷新页面重试':EnemyAssets.ready&&viewmodelReady?'作战资源已就绪':'正在准备作战资源…';if(EnemyAssets.ready&&viewmodelReady&&document.getElementById('launch'))document.getElementById('launch').innerHTML='<span class="start-cn">开始行动</span><span class="start-en">OPERATION START</span><span class="start-arrow">▶</span>' }
if(typeof Image!=='undefined'){viewmodelImage=new Image();viewmodelImage.onload=()=>{viewmodelReady=true;refreshAssetStatus()};viewmodelImage.onerror=()=>{const s=document.getElementById('assetStatus');if(s)s.textContent='第一视角素材加载失败，请刷新重试';console.error('First person artwork failed to load')};viewmodelImage.src='assets/viewmodels.png'}
function stepPresentation(dt){FPS.kickVelocity+=(-110*FPS.kick-17*FPS.kickVelocity)*dt;FPS.kick+=FPS.kickVelocity*dt;FPS.swayX*=Math.exp(-dt*9);FPS.swayY*=Math.exp(-dt*9);FPS.attack=Math.max(0,FPS.attack-dt);FPS.tracer=Math.max(0,FPS.tracer-dt);FPS.skillPulse=Math.max(0,FPS.skillPulse-dt);FPS.aim+=(Number(aimHeld)-FPS.aim)*(1-Math.exp(-dt*14));if(keys.KeyW||keys.KeyS||keys.KeyA||keys.KeyD)FPS.step+=dt*(keys.ShiftLeft?13:8);for(const s of FPS.shells){s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=600*dt;s.r+=dt*10;s.life-=dt}FPS.shells=FPS.shells.filter(s=>s.life>0)}
function kickShot(){FPS.kickVelocity+=op===0?9:op===1?4:12;FPS.attack=op===2?.48:op===1?.34:.16;FPS.tracer=.065;pitch=Math.min(H*.27,pitch+(op===0?2:op===1?1.5:0));if(op===0)FPS.shells.push({x:W*.7,y:H*.67,vx:170+Math.random()*60,vy:-160,life:.65,r:0})}
function drawReunion(e,size){const model=EnemyAssets[e.heavy?'shield':'soldier'];if(!model)return;const attack=Math.hypot(e.x-p.x,e.y-p.y)<1.2,frame=model.renderFrame(attack?'Attack':'Move_Loop',time+e.x*.13),next=map.path[e.node],side=next?-(next[0]-e.x)*Math.sin(p.a)+(next[1]-e.y)*Math.cos(p.a):1;ctx.save();ctx.fillStyle='#060e1888';ctx.beginPath();ctx.ellipse(0,0,size*.27,size*.055,0,0,7);ctx.fill();if(side<0)ctx.scale(-1,1);ctx.imageSmoothingEnabled=true;ctx.drawImage(frame,-size*.53,-size*1.29,size*1.06,size*1.29);if(e.hit>0){ctx.globalCompositeOperation='source-atop';ctx.globalCompositeOperation='source-over'}ctx.restore();ctx.fillStyle='#091018';ctx.fillRect(-size*.26,-size*1.2,size*.52,Math.max(2,size*.018));ctx.fillStyle='#ed9c72';ctx.fillRect(-size*.26,-size*1.2,size*.52*Math.max(0,e.hp/e.max),Math.max(2,size*.018))}
function drawOperator(preview=false){if(!viewmodelReady)return;const c=ctx,col=viewmodelImage.width/3,ih=viewmodelImage.height;let width=H*(preview?.48:.82),height=width*ih/col,x=preview?W*.72-width*.32:W*.56-width*.37,y=preview?H*.67-height:H-height+24,rotation=0;const moving=keys.KeyW||keys.KeyS||keys.KeyA||keys.KeyD;if(!preview){let breath=Math.sin(time*1.7)*1.8,bob=moving?Math.sin(FPS.step)*4:0;x+=FPS.swayX+Math.cos(FPS.step*.5)*(moving?2:0);y+=FPS.swayY+bob+breath+FPS.kick*20;rotation=-FPS.kick*.035;const sprint=keys.ShiftLeft&&moving&&!aimHeld;if(sprint){y+=H*.07;rotation+=.1}if(op===2&&FPS.attack>0){const f=1-FPS.attack/.48,ease=Math.sin(f*Math.PI);x-=ease*H*.24;y+=Math.sin(f*Math.PI*2)*H*.07;rotation-=ease*.68}else if(op===1&&FPS.attack>0){const f=1-FPS.attack/.34;y-=Math.sin(f*Math.PI)*18;rotation+=Math.sin(f*Math.PI)*.035}if(reload>0){const f=1-reload/1.5,tilt=Math.sin(f*Math.PI);x+=tilt*35;y+=tilt*H*.16;rotation-=tilt*.3}x+=(W*.5-(x+width*.48))*FPS.aim*.22;y-=FPS.aim*12;width*=1+FPS.aim*.06;height=width*ih/col;}
 c.save();c.translate(x+width*.5,y+height*.9);c.rotate(rotation);c.drawImage(viewmodelImage,col*op,0,col,ih,-width*.5,-height*.9,width,height);c.restore();if(!preview){drawMuzzleAndArts(x,y,width,height);drawCases();if(FPS.skillPulse>0)drawSkillEffect();if(reload>0){c.fillStyle='#edf4f0';c.font='11px sans-serif';c.textAlign='center';c.fillText(op===1?'术式回充':'更换弹匣',W/2,H*.64);c.fillStyle='#12222c';c.fillRect(W/2-55,H*.66,110,3);c.fillStyle='#e7ad72';c.fillRect(W/2-55,H*.66,110*(1-reload/1.5),3)}}}
function drawMuzzleAndArts(x,y,w,h){const c=ctx;if(op===0&&flash>0){let mx=x+w*.31,my=y+h*.43;c.save();c.translate(mx,my);c.rotate(Math.random()*Math.PI);c.shadowColor='#ffd482';c.shadowBlur=25;poly(c,[[0,-28],[6,-9],[27,-15],[13,1],[31,14],[7,10],[0,31],[-6,9],[-25,16],[-11,-1],[-30,-13],[-7,-9]],'#fff1c0',null);c.restore();c.strokeStyle='#ffe7a48c';c.lineWidth=1;c.beginPath();c.moveTo(mx,my);c.lineTo(W/2,H/2);c.stroke()}if(op===1){const mx=x+w*.42,my=y+h*.31;c.save();c.globalAlpha=.55;c.strokeStyle='#79c8fc';c.lineWidth=1.5;const r=25+(FPS.attack>0?35*(1-FPS.attack/.34):Math.sin(time*3)*3);c.beginPath();c.ellipse(mx,my,r,r*.4,-.4+time*.2,0,7);c.stroke();for(let i=0;i<6;i++){const a=time+i*Math.PI/3;poly(c,[[mx+Math.cos(a)*r,my+Math.sin(a)*r*.5],[mx+Math.cos(a)*r+4,my+Math.sin(a)*r*.5-8],[mx+Math.cos(a)*r+7,my+Math.sin(a)*r*.5+3]],'#0c1729','#71badb',1)}c.restore()}if(op===2&&FPS.attack>0){const f=1-FPS.attack/.48;c.save();c.globalAlpha=Math.sin(f*Math.PI)*.65;c.strokeStyle='#d6eeff';c.lineWidth=4;c.beginPath();c.ellipse(W*.5,H*.52,W*.32,H*.16,-.6,Math.PI*.8,Math.PI*1.8);c.stroke();c.restore()}}
function drawCases(){for(const s of FPS.shells){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.r);ctx.fillStyle='#bd915b';ctx.fillRect(-2,-5,4,10);ctx.fillStyle='#f0d9a2';ctx.fillRect(-2,-5,2,9);ctx.restore()}}
function drawSkillEffect(){const c=ctx,alpha=Math.min(.6,FPS.skillPulse/1.4);c.save();c.globalAlpha=alpha;if(op===2){for(let i=0;i<3;i++){c.strokeStyle=i===1?'#e2f6ff':'#8ebcda';c.lineWidth=3+i*3;c.beginPath();c.ellipse(W*.5,H*.5,W*(.3+i*.04),H*.15,-.4+i*.1,Math.PI*.9,Math.PI*1.94);c.stroke()}}else if(op===1){for(let i=0;i<15;i++){let a=i*2.4+time,r=H*.13+(i%4)*H*.045;poly(c,[[W/2+Math.cos(a)*r,H/2+Math.sin(a)*r],[W/2+Math.cos(a)*r+12,H/2+Math.sin(a)*r-28],[W/2+Math.cos(a)*r+20,H/2+Math.sin(a)*r+5]],'#081322','#7dc4e4',1)}}else{c.strokeStyle='#ffc071';c.lineWidth=2;c.strokeRect(W*.47,H*.45,W*.06,H*.1)}c.restore()}
